					const installed = await runAdb(operation, {
						device: input.serial,
						path: apkPath,
						localPath: digest.path
					}, selection.binary, adbArguments(input.serial, [
						"install",
						...input.replace ? ["-r"] : [],
						digest.path
					]), {
						timeoutMs: PULL_TIMEOUT_MS,
						maxOutputBytes: PULL_MAX_OUTPUT_BYTES
					}, signal);
